# Define the system of ODEs for a 2D system
system_4D <- function(t, state, parameters) {
  x <- state[1]
  y <- state[2]
  z <- state[3]
  w <- state[4]

  u <- parameters$R_interp(t)
  
  #---------------------------------------------------#
  # Equations derived from the following datasets     #
  # ice volume: "rohling2021-wh-main.txt",            #
  # co2: "antarctica2015co2.xls" and                  #
  # deep ocean temp: "sosdian2009.xls"                #
  # sea surface temp: "herbert2016-odp982.txt"        #
