parmeters <- list(R_interp = R_interp)

choose_solution <- function(xs_normalized, model_time, dt = 0.01, parms = parmeters, method = "lsoda"){
  solutions <- switch(
    as.character(ncol(xs_normalized)),
    "2" = ode(y = as.numeric(xs_normalized[1,]), times = model_time, func = system_2D, parms = parmeters, method = "lsoda", maxsteps = 50000),
    "3" = ode(y = as.numeric(xs_normalized[1,]), times = model_time, func = system_3D, parms = parmeters, method = "lsoda", maxsteps = 50000),
    "4" = ode(y = as.numeric(xs_normalized[1,]), times = model_time, func = system_4D, parms = parmeters, method = "lsoda", maxsteps = 50000),
    "5" = ode(y = as.numeric(xs_normalized[1,]), times = model_time, func = system_5D, parms = parmeters, method = "lsoda", maxsteps = 50000) 
  )

  return(solutions)
}

