  )

  lines(x = common_timescale,
        recovered_equations$x,
        col = "orange",
        lty = 3, lwd = 4)
  lines(x = common_timescale,
        recovered_equations$y,
        col = "orange",
        lty = 3, lwd = 4)
  lines(x = common_timescale,
        recovered_equations$z,
        col = "orange",
        lty = 3, lwd = 4)

  #lines(x = df.a$time, df.a$x, col = "black")
